// Photorealistic mockups generated by scripts/gen-mockups.mjs (git-ignored). Absent files simply fall back
// to the vector mockups, so the prototype runs without them.
const files = import.meta.glob('../data/mockups/*/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});

const PHOTOS = new Map<string, string>();
for (const [path, url] of Object.entries(files)) {
  const match = /mockups\/([^/]+)\/([^/]+)\.webp$/.exec(path);
  if (match && typeof url === 'string') PHOTOS.set(`${match[1]}/${match[2]}`, url);
}

export const SCENE_LABEL: Record<string, string> = {
  cards: 'Cartes de visite',
  store: 'Devanture',
  tote: 'Tote bag',
  tee: 'T-shirt',
  phone: 'Application',
  billboard: 'Affichage',
  office: 'Signalétique',
};
export const SCENES = Object.keys(SCENE_LABEL);

export const photoOf = (slug: string, scene: string): string | undefined =>
  PHOTOS.get(`${slug}/${scene}`);
export const hasPhotos = (slug: string): boolean =>
  SCENES.some((scene) => PHOTOS.has(`${slug}/${scene}`));
